using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Collections.Generic;using System.Runtime.Serialization.Json;using GlassBoard;
public static class Feedback16Tests {
    static int checks;static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
    static byte[] Json<T>(T value){using(var m=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(m,value);return m.ToArray();}}
    static void Write(string path,byte[] bytes){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,bytes);}
    public static int Main(string[] args){string work=Path.Combine(Path.GetTempPath(),"gb16-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);try{
        foreach(string ext in BoardFiles.Extensions){string path=Path.Combine(work,"中文文档"+ext);BoardFiles.Create(path);Check(File.Exists(path),"file not created");if(ext==".docx"||ext==".xlsx")using(var zip=ZipFile.OpenRead(path)){Check(zip.GetEntry("[Content_Types].xml")!=null&&zip.GetEntry("_rels/.rels")!=null,"office package missing parts");Check(zip.GetEntry(ext==".docx"?"word/document.xml":"xl/workbook.xml")!=null,"office main part missing");}byte[] before=File.ReadAllBytes(path);bool refused=false;try{BoardFiles.Create(path);}catch(IOException){refused=true;}Check(refused&&before.SequenceEqual(File.ReadAllBytes(path)),"new document overwrote existing file");}
        bool unsupported=false;try{BoardFiles.Create(Path.Combine(work,"bad.exe"));}catch(ArgumentException){unsupported=true;}Check(unsupported&&!File.Exists(Path.Combine(work,"bad.exe")),"unsupported format created");
        string folder=BoardFiles.CreateFolder(work,"中文 文件夹");File.WriteAllText(Path.Combine(folder,"keep.txt"),"keep");bool duplicate=false;try{BoardFiles.CreateFolder(work,"中文 文件夹");}catch(IOException){duplicate=true;}Check(duplicate&&File.Exists(Path.Combine(folder,"keep.txt")),"existing folder was reused");foreach(string name in new[]{"../escape","a\\b","a/b","..","bad."," ","CON","nul.txt","COM1","LPT9.log","control\u0001"}){bool denied=false;try{BoardFiles.CreateFolder(work,name);}catch(ArgumentException){denied=true;}Check(denied,"bad folder name accepted");}
        var p=new Preferences();p.Groups=new List<string>{"Work","Keep"};p.LearnedGroups["launcher"]="work";p.Apps.Add(new Entry{Name="A",Path=@"C:\offline\A.lnk",Group="WORK",ExtraGroups=new List<string>{"Keep"},Pinned=true});p.Apps.Add(new Entry{Name="B",Path=@"Z:\unmounted\B.lnk",Group="Work"});FeatureRules.DeleteGroup(p," work ");p.Normalize();Check(p.Groups.SequenceEqual(new[]{"Keep"})&&p.LearnedGroups.Count==0,"deleted group survived through spelling variant");Check(p.Apps.Count==2&&FeatureRules.InGroup(p.Apps[0],"Keep")&&FeatureRules.InGroup(p.Apps[1],"未分组"),"delete group lost entries or shared memberships");Store.Save(p);p=Store.Load();Check(p.Apps.Count==2&&p.Apps[0].Pinned&&!p.Groups.Contains("Work"),"group delete or unavailable entries lost after restart");
        byte[] committed=File.ReadAllBytes(Store.FileName);File.WriteAllText(Store.FileName,"broken");Store.Save(p);Check(File.ReadAllBytes(Store.FileName).SequenceEqual(committed),"unchanged save did not repair damaged main");File.Delete(Store.FileName);Store.Save(p);Check(File.ReadAllBytes(Store.FileName).SequenceEqual(committed),"unchanged save did not repair missing main");
        File.WriteAllText(Store.FileName+".last-good","broken");Store.Save(p);Check(File.ReadAllBytes(Store.FileName+".last-good").SequenceEqual(committed),"unchanged save did not repair failed safety copy");
        var older=new Preferences();older.Apps.Add(FeatureRules.Copy(p.Apps[0]));older.Normalize();Write(Store.FileName+".previous",Json(older));File.SetLastWriteTimeUtc(Store.FileName+".previous",DateTime.UtcNow.AddHours(-2));string snap=Path.Combine(Store.Folder,"snapshots","layout-20990101-test.json");Write(snap,committed);File.SetLastWriteTimeUtc(snap,DateTime.UtcNow.AddHours(-1));File.WriteAllText(Store.FileName,"broken");File.WriteAllText(Store.FileName+".last-good","broken");p=Store.Load();Check(p.Apps.Count==2&&Store.RecoveryMessage!=null,"older .previous beat newer readable snapshot");
        var removed=FeatureRules.Copy(p.Apps[1]);EntryRules.Remove(p,new[]{p.Apps[1].Path},"全部");Store.Save(p);File.WriteAllText(Store.FileName,"broken");p=Store.Load();Check(p.Apps.Count==1,"durability resurrected a deliberately deleted entry");
        byte[] staleJournal=File.ReadAllBytes(Path.Combine(Store.Folder,"removed.json"));EntryRecoveryRules.Restore(p,new[]{removed});Store.Save(p);Write(Path.Combine(Store.Folder,"removed.json"),staleJournal);File.WriteAllText(Store.FileName,"broken");File.WriteAllText(Store.FileName+".last-good","broken");p=Store.Load();Check(p.Apps.Count==2,"stale removal journal erased manually restored app from latest recovery snapshot");
        if(args.Length>0){Directory.CreateDirectory(args[0]);foreach(string ext in BoardFiles.Extensions)File.Copy(Path.Combine(work,"中文文档"+ext),Path.Combine(args[0],"new-document"+ext),true);}
        Console.WriteLine("PASS: "+checks+" checks: real new files, no overwrite, safe folder names, group deletion/shared membership, missing-path restart, damaged/missing primary and mirror repair, newest recovery and intentional removal.");return 0;
    }finally{Directory.Delete(work,true);if(Directory.Exists(Store.Folder))Directory.Delete(Store.Folder,true);}}
}
